describe("buildSignature — checkBalance / listBank (shared formula)", () => {
  const fixture = {
    email: "pg@merchantpgtest.com",
    timestamp: 1_700_000_000_000,
    secretKey: "de56f832487bc1ce1de5ff2cfacf8d9486c61da69df6fd61d5537b6b7d6d354d",
  } as const;

  it("matches SHA256(email + timestamp + secretKey) for checkBalance", () => {
    const expected = sha256Hex([
      fixture.email,
      fixture.timestamp,
      fixture.secretKey,
    ]);
    expect(buildSignature({ kind: "checkBalance", ...fixture })).toBe(expected);
  });

  it("listBank shares the formula with checkBalance", () => {
    const a = buildSignature({ kind: "checkBalance", ...fixture });
    const b = buildSignature({ kind: "listBank", ...fixture });
    expect(a).toBe(b);
  });
});

