describe("verifyCallbackSignature", () => {
  const secretKey = "de56f832487bc1ce1de5ff2cfacf8d9486c61da69df6fd61d5537b6b7d6d354d";
  const payload = {
    email: "pg@merchantpgtest.com",
    bankCode: "014",
    bankAccount: "1234567890",
    accountName: "BUDI WARUNG",
    custRefNumber: "pi_01HXYZ",
    amountTransfer: 15000,
    disburseId: "DSB-ABC-123",
  };

  it("accepts a correctly signed payload", () => {
    const signature = buildSignature({
      kind: "clearingCallback",
      ...payload,
      secretKey,
    });
    expect(
      verifyCallbackSignature({ ...payload, signature }, secretKey),
    ).toBe(true);
  });

  it("rejects a tampered amount", () => {
    const signature = buildSignature({
      kind: "clearingCallback",
      ...payload,
      secretKey,
    });
    expect(
      verifyCallbackSignature(
        { ...payload, amountTransfer: payload.amountTransfer + 1, signature },
        secretKey,
      ),
    ).toBe(false);
  });

  it("is case-insensitive on the received signature hex (tolerant on input, strict on output)", () => {
    const signature = buildSignature({
      kind: "clearingCallback",
      ...payload,
      secretKey,
    });
    expect(
      verifyCallbackSignature(
        { ...payload, signature: signature.toUpperCase() },
        secretKey,
      ),
    ).toBe(true);
  });
});

describe("buildTimestamp", () => {
  it("returns a Unix-ms number within ±5s of Date.now()", () => {
    const before = Date.now();
    const ts = buildTimestamp();
    const after = Date.now();
    expect(ts).toBeGreaterThanOrEqual(before);
    expect(ts).toBeLessThanOrEqual(after);
    // Must be milliseconds, not seconds. A 10-digit value would be seconds.
    expect(String(ts).length).toBeGreaterThanOrEqual(13);
  });
});
